  values ('ME', 'short_answer', 'What is avian flu? Explain the causes, symptoms, mode of transmission and preventive measures of avian flu. (3 marks)', 'Avian influenza (bird flu) is an infection caused by influenza A viruses that normally circulate in birds, such as H5N1 and H7N9, which occasionally infect humans. Cause: avian influenza A virus. Symptoms in humans: fever, cough, sore throat, muscle aches, conjunctivitis and, in severe cases, pneumonia, breathing difficulty (ARDS) and death. Transmission: close contact with infected live or dead poultry or wild birds, their droppings or contaminated surfaces, e.g. in backyard farms and live bird markets; human-to-human spread is rare. Prevention: avoid contact with sick or dead birds and report them; cook poultry and eggs thoroughly; wash hands with soap; poultry workers use PPE; surveillance, culling and disinfection of infected flocks by livestock authorities; and antiviral drugs (oseltamivir) for cases and exposed people.', null, '[{"point": "Definition and cause: bird flu - infection with avian influenza A viruses (e.g. H5N1, H7N9) of birds, occasionally infecting humans", "marks": 1}, {"point": "Symptoms (fever, cough, sore throat, myalgia, conjunctivitis, severe pneumonia/ ARDS) and transmission (close contact with infected live/ dead poultry, droppings, markets; rarely human-to-human)", "marks": 1}, {"point": "Prevention: avoid contact with sick/ dead birds, cook poultry and eggs well, hand hygiene, PPE for poultry workers, culling and surveillance, antivirals (oseltamivir) for exposed", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'medical-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
