  values ('ME', 'short_answer', 'Describe the functions of lipids in the body. (3 marks)', 'Lipids: (1) provide a concentrated source of energy (9 kcal per gram) and are stored as triglycerides in adipose tissue; (2) form the structure of cell membranes (phospholipids, cholesterol) and the myelin sheath of nerves; (3) insulate the body against heat loss and cushion and protect vital organs; (4) help absorb and transport the fat-soluble vitamins A, D, E and K; (5) are precursors of steroid hormones (cortisol, sex hormones), vitamin D and bile acids, and of signalling molecules such as prostaglandins; (6) supply essential fatty acids (omega-3 and omega-6).', null, '[{"point": "Energy: concentrated energy source (9 kcal/g) and storage in adipose tissue", "marks": 1}, {"point": "Structure: phospholipids and cholesterol in cell membranes; myelin; insulation and protection of organs", "marks": 1}, {"point": "Others: absorption and transport of fat-soluble vitamins A, D, E, K; precursors of hormones (steroid hormones, prostaglandins), bile acids; essential fatty acids", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
