  values ('ME', 'short_answer', 'Name the three ossicles of the middle ear and describe how sound waves are conducted from the outer ear to the inner ear. (3 marks)', 'The three ossicles are the malleus (hammer), incus (anvil) and stapes (stirrup). Sound conduction: the pinna collects sound waves and directs them through the external auditory canal to the tympanic membrane (eardrum), which vibrates; the vibrations pass through the malleus, incus and stapes, which amplify them; the stapes pushes on the oval window, setting up waves in the fluid of the cochlea; these bend the hair cells of the organ of Corti, which convert them into nerve impulses carried by the auditory (cochlear) nerve to the auditory cortex in the temporal lobe of the brain.', null, '[{"point": "Ossicles: malleus (hammer), incus (anvil), stapes (stirrup)", "marks": 1}, {"point": "Pathway: pinna collects → external auditory canal → tympanic membrane vibrates → ossicles amplify → stapes at oval window → fluid waves in cochlea → hair cells (organ of Corti) → auditory nerve → brain (temporal lobe)", "marks": 2}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'medical-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
